const openFieldGap = `-- name: OpenFieldGap :exec
INSERT INTO pfas.field_data_gaps (id, field_id, code, detail, resolution, status)
VALUES ($1, $2, $3, $4, $5, 'OPEN')
ON CONFLICT (field_id, code) DO UPDATE
SET detail = EXCLUDED.detail,
    resolution = EXCLUDED.resolution,
    status = 'OPEN',
    resolved_at = NULL
`

type OpenFieldGapParams struct {
	ID         uuid.UUID `json:"id"`
	FieldID    uuid.UUID `json:"field_id"`
	Code       string    `json:"code"`
	Detail     string    `json:"detail"`
	Resolution string    `json:"resolution"`
}

func (q *Queries) OpenFieldGap(ctx context.Context, arg OpenFieldGapParams) error {
	_, err := q.db.Exec(ctx, openFieldGap,
		arg.ID,
		arg.FieldID,
		arg.Code,
		arg.Detail,
		arg.Resolution,
	)
	return err
}

