const updateCandidateFieldDetails = `-- name: UpdateCandidateFieldDetails :execrows
UPDATE pfas.candidate_fields
SET mienviro_site_id = $3,
    rmp_approved = $4,
    rmp_document_reference = $5,
    usable_acres = $6,
    crop_or_use = $7,
    agronomic_rate_dry_tons_acre = $8,
    prior_loading_dry_tons = $9,
    known_constraints = $10,
    access_constraints = $11,
    updated_at = now()
WHERE id = $1 AND workspace_id = $2
`

type UpdateCandidateFieldDetailsParams struct {
	ID                       uuid.UUID      `json:"id"`
	WorkspaceID              uuid.UUID      `json:"workspace_id"`
	MienviroSiteID           *string        `json:"mienviro_site_id"`
	RmpApproved              *bool          `json:"rmp_approved"`
	RmpDocumentReference     *string        `json:"rmp_document_reference"`
	UsableAcres              pgtype.Numeric `json:"usable_acres"`
	CropOrUse                *string        `json:"crop_or_use"`
	AgronomicRateDryTonsAcre pgtype.Numeric `json:"agronomic_rate_dry_tons_acre"`
	PriorLoadingDryTons      pgtype.Numeric `json:"prior_loading_dry_tons"`
	KnownConstraints         *string        `json:"known_constraints"`
	AccessConstraints        *string        `json:"access_constraints"`
}

func (q *Queries) UpdateCandidateFieldDetails(ctx context.Context, arg UpdateCandidateFieldDetailsParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateCandidateFieldDetails,
		arg.ID,
		arg.WorkspaceID,
		arg.MienviroSiteID,
		arg.RmpApproved,
		arg.RmpDocumentReference,
		arg.UsableAcres,
		arg.CropOrUse,
		arg.AgronomicRateDryTonsAcre,
		arg.PriorLoadingDryTons,
		arg.KnownConstraints,
		arg.AccessConstraints,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const validateFieldGeometry = `-- name: ValidateFieldGeometry :one
WITH candidate AS (
    SELECT extensions.ST_Multi(
        extensions.ST_SetSRID(extensions.ST_GeomFromGeoJSON($1), 4326)
    ) AS geometry
)
SELECT CAST(extensions.ST_IsValid(geometry) AS boolean) AS is_valid,
       CAST(extensions.ST_IsValidReason(geometry) AS text) AS reason,
       CAST(NOT extensions.ST_IsEmpty(geometry) AS boolean) AS has_area,
       CAST(extensions.GeometryType(geometry) AS text) AS geometry_type
FROM candidate
`

type ValidateFieldGeometryRow struct {
	IsValid      bool   `json:"is_valid"`
	Reason       string `json:"reason"`
	HasArea      bool   `json:"has_area"`
	GeometryType string `json:"geometry_type"`
}

func (q *Queries) ValidateFieldGeometry(ctx context.Context, geojson interface{}) (ValidateFieldGeometryRow, error) {
	row := q.db.QueryRow(ctx, validateFieldGeometry, geojson)
	var i ValidateFieldGeometryRow
	err := row.Scan(
		&i.IsValid,
		&i.Reason,
		&i.HasArea,
		&i.GeometryType,
	)
	return i, err
}
